package store.service;
import store.model.*;import store.repository.Repositories;import java.io.*;import java.util.*;import java.util.stream.*;
public final class StoreService{
 public final Catalog catalog; public final Repositories db=new Repositories(); public final List<Promotion> promotions=new ArrayList<>(); private int cartNo=1;
 public StoreService(Catalog c){catalog=c;}
 public void register(Customer c){db.customer(c);} public void register(Supplier s){db.supplier(s);}
 public void registerPromotion(Promotion p){if(p==null)throw new IllegalArgumentException("Promotion is required");promotions.add(p);}
 public void initializeStock(String id,int q){catalog.product(id).increaseStock(q);} public Cart createCart(String customerId){Customer c=customer(customerId);Cart x=new Cart("CART"+cartNo++,c);db.carts.put(x.id(),x);return x;} public Customer customer(String id){Customer c=db.customers.get(id);if(c==null)throw new IllegalArgumentException("Unknown customer");return c;}
 public Order createOrder(String id,Cart cart){if(db.orders.containsKey(id))throw new IllegalArgumentException("Duplicate order");if(cart.empty())throw new IllegalArgumentException("Empty cart");for(CartItem i:cart.items())i.product().decreaseStock(i.quantity());Order o=new Order(id,cart.customer(),cart.items());db.orders.put(id,o);return o;}
 public void applyPromotion(Order o,Promotion p){if(o.status()!=OrderStatus.CREATED)throw new IllegalStateException("Order not editable");o.discount(p.discount(o));}public void applyShipping(Order o,ShippingRule r){o.shipping(r.apply());}
 public void pay(String id,String paymentId,PaymentMethod method){Order o=order(id);if(o.status()==OrderStatus.CANCELLED)throw new IllegalStateException("Cancelled order");if(o.status()==OrderStatus.PAID)throw new IllegalStateException("Already paid");Payment p=new Payment(paymentId,id,o.total(),method);db.payments.put(paymentId,p);o.status(OrderStatus.PAID);db.cashflow.add(new CashflowEntry(paymentId,CashflowType.INFLOW,p.amount(),"Payment for "+id));}
 public void cancel(String id){Order o=order(id);if(o.status()==OrderStatus.PAID)throw new IllegalStateException("Paid order cannot cancel");if(o.status()==OrderStatus.CANCELLED)throw new IllegalStateException("Already cancelled");for(OrderItem i:o.items())i.product().increaseStock(i.quantity());o.status(OrderStatus.CANCELLED);}
 public Order order(String id){Order o=db.orders.get(id);if(o==null)throw new IllegalArgumentException("Unknown order");return o;}
 public ReturnRequest requestReturn(String id,String orderId){Order o=order(orderId);if(o.status()!=OrderStatus.PAID&&o.status()!=OrderStatus.PARTIALLY_RETURNED)throw new IllegalStateException("Only paid orders can return");ReturnRequest r=new ReturnRequest(id,o);db.returns.put(id,r);return r;}
 public void addReturnItem(ReturnRequest r,String productId,int q){if(q<=0)throw new IllegalArgumentException("Invalid return quantity");OrderItem source=r.order().items().stream().filter(i->i.product().id().equals(productId)).findFirst().orElseThrow(()->new IllegalArgumentException("Product not in order"));long already=r.items().stream().filter(i->i.product().id().equals(productId)).mapToLong(ReturnItem::quantity).sum();if(already+q>source.quantity())throw new IllegalArgumentException("Return exceeds purchased quantity");r.add(new ReturnItem(source.product(),q,source.unitPrice()));}
 public void processReturn(ReturnRequest r){if(r.items().isEmpty())throw new IllegalArgumentException("Return needs items");if(r.processed())throw new IllegalStateException("Already processed");for(ReturnItem i:r.items())i.product().increaseStock(i.quantity());db.cashflow.add(new CashflowEntry(r.id(),CashflowType.OUTFLOW,r.refundTotal(),"Refund for "+r.order().id()));r.markProcessed();r.order().status(OrderStatus.RETURNED);}
 public Restock restock(String id,String productId,String supplierId,int q,double cost){Product p=catalog.product(productId);Supplier s=db.suppliers.get(supplierId);if(s==null)throw new IllegalArgumentException("Unknown supplier");Restock r=new Restock(id,p,s,q,cost);p.increaseStock(q);db.restocks.put(id,r);db.cashflow.add(new CashflowEntry(id,CashflowType.OUTFLOW,r.total(),"Restock "+productId));return r;}
 public void manualOutflow(String id,double amount,String desc){db.cashflow.add(new CashflowEntry(id,CashflowType.OUTFLOW,amount,desc));}
 public void exportInventory(String filename)throws IOException{try(PrintWriter w=new PrintWriter(filename)){w.println("product_id,name,category,stock,unit_price");for(Product p:catalog.products())w.printf(Locale.US,"%s,%s,%s,%d,%.2f%n",p.id(),p.name(),p.category().name(),p.stock(),p.unitPrice());}}
 public void exportCashflow(String filename)throws IOException{try(PrintWriter w=new PrintWriter(filename)){w.println("id,type,amount,description");for(CashflowEntry e:db.cashflow)w.printf(Locale.US,"%s,%s,%.2f,%s%n",e.id(),e.type(),e.amount(),e.description());}}
 public double inflow(){return db.cashflow.stream().filter(e->e.type()==CashflowType.INFLOW).mapToDouble(CashflowEntry::amount).sum();}public double outflow(){return db.cashflow.stream().filter(e->e.type()==CashflowType.OUTFLOW).mapToDouble(CashflowEntry::amount).sum();}public double net(){return inflow()-outflow();}
 public Map<String,Integer> sold(){Map<String,Integer> m=new TreeMap<>();for(Product p:catalog.products())m.put(p.id(),0);for(Order o:db.orders.values())if(o.status()!=OrderStatus.CANCELLED)for(OrderItem i:o.items())m.merge(i.product().id(),i.quantity(),Integer::sum);return m;}public Map<OrderStatus,Long> statusCounts(){return Arrays.stream(OrderStatus.values()).collect(Collectors.toMap(s->s,s->db.orders.values().stream().filter(o->o.status()==s).count(),(a,b)->a,()->new EnumMap<>(OrderStatus.class)));}
}
